import{_ as t,o as r,c as o,a5 as a}from"./chunks/framework.d5iMQeUW.js";const u=JSON.parse('{"title":"Portal server library","description":"","frontmatter":{},"headers":[],"relativePath":"reference/components/portal/portal-server-lib.md","filePath":"reference/components/portal/portal-server-lib.md"}'),d={name:"reference/components/portal/portal-server-lib.md"};function i(n,e,c,s,l,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="portal-server-library" tabindex="-1">Portal server library <a class="header-anchor" href="#portal-server-library" aria-label="Permalink to &quot;Portal server library&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>The <strong>Portal server library</strong> (<code>@platform-mesh/portal-server-lib</code>) is the NestJS library the <a href="./../portal.html">Portal</a> backend is built with. It builds on the generic <a href="https://www.npmjs.com/package/@openmfp/portal-server-lib" target="_blank" rel="noreferrer"><code>@openmfp/portal-server-lib</code></a>, which provides the <code>PortalModule</code> that serves the frontend, handles the OAuth2 flow, and assembles the Luigi configuration. The Platform Mesh library supplies the implementations that connect that module to kcp, Keycloak, and the Platform Mesh authorization stack.</p><h2 id="provided-implementations" tabindex="-1">Provided implementations <a class="header-anchor" href="#provided-implementations" aria-label="Permalink to &quot;Provided implementations&quot;">​</a></h2><p>The library exports its providers from <code>@platform-mesh/portal-server-lib/portal-options</code>. The Portal backend passes them to <code>PortalModule.create()</code>:</p><table tabindex="0"><thead><tr><th>Export</th><th>Implements</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>PMAuthConfigProvider</code></td><td><code>AuthConfigService</code></td><td>Resolves the organization from the request host, reads the OIDC client from the <code>IdentityProviderConfiguration</code> resource in kcp, and returns the authorization and token endpoints from OIDC discovery</td></tr><tr><td><code>PMLogoutService</code></td><td><code>LogoutCallback</code></td><td>Ends the session at the identity provider on logout</td></tr><tr><td><code>PMRequestContextProvider</code></td><td><code>RequestContextProvider</code></td><td>Adds the organization and whether the request targets an organization subdomain to the request context</td></tr><tr><td><code>PMPortalContextService</code></td><td><code>PortalContextProvider</code></td><td>Resolves <code>${org-name}</code> and <code>${org-subdomain}</code> placeholders in portal context URLs and adds the public kcp workspace URL</td></tr><tr><td><code>AccountEntityContextProvider</code></td><td><code>EntityContextProvider</code></td><td>Provides the context values for the <code>account</code> entity</td></tr><tr><td><code>KubernetesServiceProvidersService</code></td><td><code>ServiceProviderService</code></td><td>Lists <a href="/main/reference/resources/content-configuration.html"><code>ContentConfiguration</code></a> resources for the current organization and account through kcp, and returns them together with the resolved node permissions</td></tr><tr><td><code>ContentConfigurationServiceProvidersService</code></td><td><code>ServiceProviderService</code></td><td>Alternative service provider that reads <code>ContentConfiguration</code> resources through the <code>contentconfigurations</code> <a href="./../virtual-workspaces.html">virtual workspace</a> of the <a href="./../kubernetes-graphql-gateway.html">Kubernetes GraphQL gateway</a></td></tr><tr><td><code>KcpKubernetesService</code></td><td>—</td><td>Kubernetes client for kcp, configured from <code>KUBECONFIG_KCP</code></td></tr><tr><td><code>PermissionsProxyService</code>, <code>AuthzWebhookService</code></td><td>—</td><td>Resolve navigation node and resource instance permissions through the <code>/batch-authz</code> endpoint of the <a href="./../rebac-authz-webhook.html">rebac-authz-webhook</a>, configured by <code>OPENMFP_PORTAL_CONTEXT_AUTHZ_WEBHOOK_URL</code>; when unset, permission checks fail open</td></tr><tr><td><code>PermissionsController</code></td><td>—</td><td>Exposes <code>POST /rest/permissions/resource-check</code> for instance-level permission checks from the frontend</td></tr></tbody></table><p>Outside an organization subdomain, both service providers return the welcome node configuration instead of <code>ContentConfiguration</code> resources.</p><h2 id="repository" tabindex="-1">Repository <a class="header-anchor" href="#repository" aria-label="Permalink to &quot;Repository&quot;">​</a></h2><ul><li><a href="https://github.com/platform-mesh/portal-server-lib" target="_blank" rel="noreferrer">github.com/platform-mesh/portal-server-lib</a></li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../portal.html">Portal</a></li><li><a href="./portal-ui-lib.html">Portal UI library</a></li><li><a href="./../keycloak.html">Keycloak</a></li><li><a href="./../rebac-authz-webhook.html">rebac-authz-webhook</a></li></ul>',11)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
